css:
body {
 background: #333;
}
 #loader-2 {
  display: inline-flex;
  gap: 5px;
  animation: l2-0 1s infinite linear;
  background: darkgray;
}
#loader-2::before,
#loader-2::after {
  content: '';
  width: 35px;
  aspect-ratio: 1;
  box-shadow: 0 0 0 3px inset #fff;
  animation: l2-1 1s infinite linear both;
}
#loader-2::after {
  animation-direction: reverse;
}
@keyframes l2-0 {
  0% {transform: rotate(0deg)}
  80%, 100% {transform: rotate(180deg)}
}
@keyframes l2-1 {
  0%, 20% {border-radius: 0}
  80%, 100% {border-radius: 50%}
}
